173	import java.math.BigDecimal;
174	import java.time.LocalDate;
175	
176	public final class Reservation {
177	
178	    private final long id;
179	    private final int roomNumber;
180	    private final Guest guest;
181	    private final LocalDate checkIn;
182	    private final LocalDate checkOut;
183	    private final int guests;
184	    private final RatePlan ratePlan;
185	    private final Price price;
186	    private ReservationStatus status;
187	    private BigDecimal amountPaid;
188	    private BigDecimal refund;
189	
190	    Reservation(long id, NewReservation request, Price price) {
191	        this(id, request, price, ReservationStatus.PENDING, PriceCalculator.cents(BigDecimal.ZERO), null);
192	    }
193	
194	    Reservation(
195	            long id,
196	            NewReservation request,
197	            Price price,
198	            ReservationStatus status,
199	            BigDecimal amountPaid,
200	            BigDecimal refund) {
201	        this.id = id;
202	        this.roomNumber = request.roomNumber();
203	        this.guest = request.guest();
204	        this.checkIn = request.checkIn();
205	        this.checkOut = request.checkOut();
206	        this.guests = request.guests();
207	        this.ratePlan = request.ratePlan();
208	        this.price = price;
209	        this.status = status;
210	        this.amountPaid = amountPaid;
211	        this.refund = refund;
212	    }
213	
214	    public long id() {
215	        return id;
216	    }
217	
218	    public int roomNumber() {
219	        return roomNumber;
220	    }
221	
222	    public Guest guest() {
223	        return guest;
224	    }
225	
226	    public LocalDate checkIn() {
227	        return checkIn;
228	    }
229	
230	    public LocalDate checkOut() {
231	        return checkOut;
232	    }
233	
234	    public int guests() {
235	        return guests;
236	    }
237	
238	    public RatePlan ratePlan() {
239	        return ratePlan;
240	    }
241	
242	    public Price price() {
243	        return price;
244	    }
245	
246	    public ReservationStatus status() {
247	        return status;
248	    }
249	
250	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
251	    public BigDecimal amountPaid() {
252	        return amountPaid;
253	    }
254	
255	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
256	    public BigDecimal refund() {
257	        return refund;
258	    }
259	
260	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
261	    public boolean isPaid() {
262	        return status == ReservationStatus.CONFIRMED
263	                || status == ReservationStatus.CHECKED_IN
264	                || status == ReservationStatus.CHECKED_OUT;
265	    }
266	
267	    /** The money the inn keeps from this reservation. */
268	    public BigDecimal amountKept() {
269	        return refund == null ? amountPaid : amountPaid.subtract(refund);
270	    }
271	
272	    void changeStatus(ReservationStatus newStatus) {
273	        this.status = newStatus;
274	    }
275	
276	    void confirmPayment() {
277	        this.status = ReservationStatus.CONFIRMED;
278	        this.amountPaid = price.total();
279	    }
280	
281	    void cancel(BigDecimal refundAmount) {
282	        this.status = ReservationStatus.CANCELLED;
283	        this.refund = refundAmount;
284	    }
285	}

